#version 300 es

#define HLSLCC_ENABLE_UNIFORM_BUFFERS 1
#if HLSLCC_ENABLE_UNIFORM_BUFFERS
#define UNITY_UNIFORM
#else
#define UNITY_UNIFORM uniform
#endif
#define UNITY_SUPPORTS_UNIFORM_LOCATION 0
#if UNITY_SUPPORTS_UNIFORM_LOCATION
#define UNITY_LOCATION(x) layout(location = x)
#define UNITY_BINDING(x) layout(binding = x, std140)
#else
#define UNITY_LOCATION(x)
#define UNITY_BINDING(x) layout(std140)
#endif
uniform 	mediump float _HG_UV_ROTATION;
uniform 	mediump vec4 _Rotation0;
uniform 	mediump vec4 _Rotation1;
uniform 	mediump vec4 _Rotation2;
uniform 	mediump vec4 _Rotation3;
uniform 	vec4 _MainTex_ST;
uniform 	vec4 _DissolveTex_ST;
uniform 	vec4 _DisturbTex_ST;
uniform 	vec4 _RamTex_ST;
uniform 	mediump float _MainUSpeed;
uniform 	mediump float _MainVSpeed;
uniform 	mediump float _DissolveUSpeed;
uniform 	mediump float _DissolveVSpeed;
uniform 	mediump float _DisturbUSpeed;
uniform 	mediump float _DisturbVSpeed;
#if HLSLCC_ENABLE_UNIFORM_BUFFERS
UNITY_BINDING(0) uniform UnityPerCamera {
#endif
	UNITY_UNIFORM vec4 _Time;
	UNITY_UNIFORM vec4 _SinTime;
	UNITY_UNIFORM vec4 _CosTime;
	UNITY_UNIFORM vec4 unity_DeltaTime;
	UNITY_UNIFORM vec3 _WorldSpaceCameraPos;
	UNITY_UNIFORM vec4 _ProjectionParams;
	UNITY_UNIFORM vec4 _ScreenParams;
	UNITY_UNIFORM vec4 _ZBufferParams;
	UNITY_UNIFORM vec4 unity_OrthoParams;
#if HLSLCC_ENABLE_UNIFORM_BUFFERS
};
#endif
#if HLSLCC_ENABLE_UNIFORM_BUFFERS
UNITY_BINDING(1) uniform UnityPerDraw {
#endif
	UNITY_UNIFORM vec4 hlslcc_mtx4x4unity_ObjectToWorld[4];
	UNITY_UNIFORM vec4 hlslcc_mtx4x4unity_WorldToObject[4];
	UNITY_UNIFORM vec4 unity_LODFade;
	UNITY_UNIFORM vec4 unity_WorldTransformParams;
	UNITY_UNIFORM vec4 unity_RenderingLayer;
	UNITY_UNIFORM mediump vec4 unity_LightData;
	UNITY_UNIFORM mediump vec4 unity_LightIndices[2];
	UNITY_UNIFORM vec4 unity_ProbesOcclusion;
	UNITY_UNIFORM vec4 unity_SpecCube0_BoxMax;
	UNITY_UNIFORM vec4 unity_SpecCube0_BoxMin;
	UNITY_UNIFORM vec4 unity_SpecCube0_ProbePosition;
	UNITY_UNIFORM mediump vec4 unity_SpecCube0_HDR;
	UNITY_UNIFORM vec4 unity_SpecCube1_BoxMax;
	UNITY_UNIFORM vec4 unity_SpecCube1_BoxMin;
	UNITY_UNIFORM vec4 unity_SpecCube1_ProbePosition;
	UNITY_UNIFORM mediump vec4 unity_SpecCube1_HDR;
	UNITY_UNIFORM vec4 unity_LightmapST;
	UNITY_UNIFORM vec4 unity_DynamicLightmapST;
	UNITY_UNIFORM mediump vec4 unity_SHAr;
	UNITY_UNIFORM mediump vec4 unity_SHAg;
	UNITY_UNIFORM mediump vec4 unity_SHAb;
	UNITY_UNIFORM mediump vec4 unity_SHBr;
	UNITY_UNIFORM mediump vec4 unity_SHBg;
	UNITY_UNIFORM mediump vec4 unity_SHBb;
	UNITY_UNIFORM mediump vec4 unity_SHC;
#if HLSLCC_ENABLE_UNIFORM_BUFFERS
};
#endif
#if HLSLCC_ENABLE_UNIFORM_BUFFERS
UNITY_BINDING(2) uniform UnityPerFrame {
#endif
	UNITY_UNIFORM mediump vec4 glstate_lightmodel_ambient;
	UNITY_UNIFORM mediump vec4 unity_AmbientSky;
	UNITY_UNIFORM mediump vec4 unity_AmbientEquator;
	UNITY_UNIFORM mediump vec4 unity_AmbientGround;
	UNITY_UNIFORM mediump vec4 unity_IndirectSpecColor;
	UNITY_UNIFORM vec4 hlslcc_mtx4x4glstate_matrix_projection[4];
	UNITY_UNIFORM vec4 hlslcc_mtx4x4unity_MatrixV[4];
	UNITY_UNIFORM vec4 hlslcc_mtx4x4unity_MatrixInvV[4];
	UNITY_UNIFORM vec4 hlslcc_mtx4x4unity_MatrixVP[4];
	UNITY_UNIFORM int unity_StereoEyeIndex;
	UNITY_UNIFORM mediump vec4 unity_ShadowColor;
#if HLSLCC_ENABLE_UNIFORM_BUFFERS
};
#endif
in highp vec4 in_POSITION0;

in mediump vec2 in_TEXCOORD0;
uniform mediump vec2 arkMainUVOffset;
in mediump vec4 in_COLOR0;
out mediump vec4 vs_TEXCOORD0;
out mediump vec4 vs_COLOR0;
out mediump vec4 vs_TEXCOORD1;
out mediump vec2 vs_TEXCOORD2;
vec4 u_xlat0;
vec4 u_xlat1;
mediump vec2 u_xlat16_2;
vec2 u_xlat3;
vec2 u_xlat8;
bool u_xlatb9;
vec2 u_xlat11;
void main()
{
    u_xlat0 = in_POSITION0.yyyy * hlslcc_mtx4x4unity_ObjectToWorld[1];
    u_xlat0 = hlslcc_mtx4x4unity_ObjectToWorld[0] * in_POSITION0.xxxx + u_xlat0;
    u_xlat0 = hlslcc_mtx4x4unity_ObjectToWorld[2] * in_POSITION0.zzzz + u_xlat0;
    u_xlat0 = u_xlat0 + hlslcc_mtx4x4unity_ObjectToWorld[3];
    u_xlat1 = u_xlat0.yyyy * hlslcc_mtx4x4unity_MatrixVP[1];
    u_xlat1 = hlslcc_mtx4x4unity_MatrixVP[0] * u_xlat0.xxxx + u_xlat1;
    u_xlat1 = hlslcc_mtx4x4unity_MatrixVP[2] * u_xlat0.zzzz + u_xlat1;
    gl_Position = hlslcc_mtx4x4unity_MatrixVP[3] * u_xlat0.wwww + u_xlat1;
    u_xlat0.xy = vec2(_MainUSpeed, _MainVSpeed) * _Time.yy;
    u_xlat0.xy = fract(u_xlat0.xy);
    u_xlat8.xy = in_TEXCOORD0.xy * _MainTex_ST.xy + _MainTex_ST.zw;
    u_xlat16_2.xy = u_xlat8.xy + vec2(-0.5, -0.5);
    u_xlat1.x = dot(u_xlat16_2.xy, _Rotation0.xz);
    u_xlat1.y = dot(u_xlat16_2.xy, _Rotation0.yw);
    u_xlat1.xy = u_xlat1.xy + vec2(0.5, 0.5);
    u_xlatb9 = 0.5<_HG_UV_ROTATION;
    u_xlat16_2.xy = (bool(u_xlatb9)) ? u_xlat1.xy : u_xlat8.xy;
    u_xlat0.xy = u_xlat0.xy + u_xlat16_2.xy;
    u_xlat1.xy = in_TEXCOORD0.xy * _DissolveTex_ST.xy + _DissolveTex_ST.zw;
    u_xlat16_2.xy = u_xlat1.xy + vec2(-0.5, -0.5);
    u_xlat11.x = dot(u_xlat16_2.xy, _Rotation1.xz);
    u_xlat11.y = dot(u_xlat16_2.xy, _Rotation1.yw);
    u_xlat3.xy = u_xlat11.xy + vec2(0.5, 0.5);
    u_xlat16_2.xy = (bool(u_xlatb9)) ? u_xlat3.xy : u_xlat1.xy;
    u_xlat1.xy = vec2(_DissolveUSpeed, _DissolveVSpeed) * _Time.yy;
    u_xlat1.xy = fract(u_xlat1.xy);
    u_xlat0.zw = u_xlat1.xy + u_xlat16_2.xy;
    vs_TEXCOORD0 = u_xlat0;
    vs_COLOR0 = in_COLOR0;
    u_xlat0.xy = in_TEXCOORD0.xy * _DisturbTex_ST.xy + _DisturbTex_ST.zw;
    u_xlat16_2.xy = u_xlat0.xy + vec2(-0.5, -0.5);
    u_xlat8.x = dot(u_xlat16_2.xy, _Rotation3.xz);
    u_xlat8.y = dot(u_xlat16_2.xy, _Rotation3.yw);
    u_xlat8.xy = u_xlat8.xy + vec2(0.5, 0.5);
    u_xlat16_2.xy = (bool(u_xlatb9)) ? u_xlat8.xy : u_xlat0.xy;
    u_xlat0.xy = vec2(_DisturbUSpeed, _DisturbVSpeed) * _Time.yy;
    u_xlat0.xy = fract(u_xlat0.xy);
    u_xlat0.xy = u_xlat0.xy + u_xlat16_2.xy;
    vs_TEXCOORD1.zw = u_xlat0.xy;
    u_xlat0.xy = in_TEXCOORD0.xy * _RamTex_ST.xy + _RamTex_ST.zw;
    u_xlat16_2.xy = u_xlat0.xy + vec2(-0.5, -0.5);
    u_xlat1.x = dot(u_xlat16_2.xy, _Rotation2.xz);
    u_xlat1.y = dot(u_xlat16_2.xy, _Rotation2.yw);
    u_xlat8.xy = u_xlat1.xy + vec2(0.5, 0.5);
    vs_TEXCOORD1.xy = (bool(u_xlatb9)) ? u_xlat8.xy : u_xlat0.xy;
    vs_TEXCOORD2.xy = vec2(0.0, 0.0);
    return;
}

shaders.fragment:
#version 300 es

precision highp float;
precision highp int;
#define HLSLCC_ENABLE_UNIFORM_BUFFERS 1
#if HLSLCC_ENABLE_UNIFORM_BUFFERS
#define UNITY_UNIFORM
#else
#define UNITY_UNIFORM uniform
#endif
#define UNITY_SUPPORTS_UNIFORM_LOCATION 0
#if UNITY_SUPPORTS_UNIFORM_LOCATION
#define UNITY_LOCATION(x) layout(location = x)
#define UNITY_BINDING(x) layout(binding = x, std140)
#else
#define UNITY_LOCATION(x)
#define UNITY_BINDING(x) layout(std140)
#endif
uniform 	mediump float _MainTexChannel;
uniform 	mediump float _DisturbTexChannel;
uniform 	mediump float _DissolvTexChannel;
uniform 	mediump float _RamTexChannel;
uniform 	mediump vec4 _MainColor;
uniform 	mediump float _Opacity;
uniform 	float _PremultiplyAlpha;
uniform 	mediump float _DisturbInfluenceDissolveUV;
uniform 	mediump float _DisturbInfluenceMainUV;
uniform 	mediump float _Amount;
uniform 	mediump float _BorderWidth;
uniform 	mediump float _IntensityU;
uniform 	mediump float _IntensityV;
UNITY_LOCATION(0) uniform mediump sampler2D _RamTex;
UNITY_LOCATION(1) uniform mediump sampler2D _DisturbTex;
UNITY_LOCATION(2) uniform mediump sampler2D _MainTex;
UNITY_LOCATION(3) uniform mediump sampler2D _DissolveTex;
in mediump vec4 vs_TEXCOORD0;
in mediump vec4 vs_COLOR0;
in mediump vec4 vs_TEXCOORD1;
in mediump vec2 vs_TEXCOORD2;
layout(location = 0) out mediump vec4 SV_Target0;
mediump float u_xlat16_0;
mediump vec4 u_xlat16_1;
vec4 u_xlat2;
mediump vec4 u_xlat16_2;
vec4 u_xlat3;
mediump vec4 u_xlat16_3;
bvec4 u_xlatb3;
bvec4 u_xlatb4;
bvec4 u_xlatb5;
mediump vec3 u_xlat16_6;
mediump float u_xlat16_7;
void main()
{
    u_xlat16_0 = vs_TEXCOORD2.x + _Amount;
    u_xlat16_1 = vs_TEXCOORD2.yyyy + vec4(_IntensityU, _IntensityV, _IntensityU, _IntensityV);
    u_xlat2 = texture(_RamTex, vs_TEXCOORD1.xy);
    u_xlatb3 = equal(vec4(vec4(_RamTexChannel, _RamTexChannel, _RamTexChannel, _RamTexChannel)), vec4(0.0, 1.0, 2.0, 3.0));
    u_xlat16_6.x = (u_xlatb3.w) ? u_xlat2.z : u_xlat2.w;
    u_xlat16_6.x = (u_xlatb3.z) ? u_xlat2.y : u_xlat16_6.x;
    u_xlat16_6.x = (u_xlatb3.y) ? u_xlat2.x : u_xlat16_6.x;
    u_xlat16_2 = (u_xlatb3.x) ? u_xlat2 : u_xlat16_6.xxxx;
    u_xlat3 = texture(_DisturbTex, vs_TEXCOORD1.zw);
    u_xlatb4 = equal(vec4(_DisturbTexChannel, _DisturbTexChannel, _DisturbTexChannel, _MainTexChannel), vec4(0.0, 1.0, 2.0, 0.0));
    u_xlat16_6.x = (u_xlatb4.z) ? u_xlat3.z : u_xlat3.w;
    u_xlat16_6.x = (u_xlatb4.y) ? u_xlat3.y : u_xlat16_6.x;
    u_xlat16_6.x = (u_xlatb4.x) ? u_xlat3.x : u_xlat16_6.x;
    u_xlat16_1 = u_xlat16_1 * u_xlat16_6.xxxx;
    u_xlat16_1 = u_xlat16_1 * vec4(_DisturbInfluenceMainUV, _DisturbInfluenceMainUV, _DisturbInfluenceDissolveUV, _DisturbInfluenceDissolveUV) + vs_TEXCOORD0;
    u_xlat3 = texture(_MainTex, u_xlat16_1.xy);
    u_xlatb5 = equal(vec4(_MainTexChannel, _MainTexChannel, _MainTexChannel, _DissolvTexChannel), vec4(1.0, 2.0, 3.0, 0.0));
    u_xlat16_6.x = (u_xlatb5.z) ? u_xlat3.z : u_xlat3.w;
    u_xlat16_6.x = (u_xlatb5.y) ? u_xlat3.y : u_xlat16_6.x;
    u_xlat16_6.x = (u_xlatb5.x) ? u_xlat3.x : u_xlat16_6.x;
    u_xlat16_3 = (u_xlatb4.w) ? u_xlat3 : u_xlat16_6.xxxx;
    u_xlat16_3 = u_xlat16_3 * _MainColor;
    u_xlat16_3 = u_xlat16_3 * vs_COLOR0;
    u_xlat16_2 = u_xlat16_2 * u_xlat16_3;
    u_xlat16_6.xyz = u_xlat16_2.xyz * vec3(2.0, 2.0, 2.0);
    u_xlat16_1.x = dot(u_xlat16_2.ww, vec2(_Opacity));
    u_xlat2 = texture(_DissolveTex, u_xlat16_1.zw);
    u_xlatb4.xy = equal(vec4(vec4(_DissolvTexChannel, _DissolvTexChannel, _DissolvTexChannel, _DissolvTexChannel)), vec4(1.0, 2.0, 0.0, 0.0)).xy;
    u_xlat16_7 = (u_xlatb4.y) ? u_xlat2.z : u_xlat2.w;
    u_xlat16_7 = (u_xlatb4.x) ? u_xlat2.y : u_xlat16_7;
    u_xlat16_7 = (u_xlatb5.w) ? u_xlat2.x : u_xlat16_7;
    u_xlat16_7 = (-u_xlat16_0) + u_xlat16_7;
    u_xlat16_0 = u_xlat16_0 + 0.5;
    u_xlat16_0 = roundEven(u_xlat16_0);
    u_xlat16_0 = (-u_xlat16_0) + 1.0;
    u_xlat16_0 = _BorderWidth * u_xlat16_0 + u_xlat16_7;
    u_xlat16_0 = u_xlat16_0 / _BorderWidth;
    u_xlat16_0 = clamp(u_xlat16_0, 0.0, 1.0);
    u_xlat16_0 = u_xlat16_0 * u_xlat16_1.x;
    u_xlat16_0 = clamp(u_xlat16_0, 0.0, 1.0);
    u_xlatb4.x = _PremultiplyAlpha<1.5;
    if(u_xlatb4.x){
        u_xlat16_1.xyz = vec3(u_xlat16_0) * u_xlat16_6.xyz;
        SV_Target0.xyz = u_xlat16_1.xyz + u_xlat16_1.xyz;
        SV_Target0.w = u_xlat16_0;
        return;
    }
    SV_Target0.xyz = u_xlat16_6.xyz;
    SV_Target0.w = u_xlat16_0;
    return;
}

